\begin{ex}%[9H5V1-3]
Tính diện tích của một tam giác đều, biết bán kính đường tròn ngoại tiếp tam giác đó là ${6}cm$. \loigiai{
\begin{center}

\begin{tikzpicture}
    % Vẽ đường tròn tâm O bán kính 3
    \draw[thick] (0,0) circle (3);

    % Định nghĩa điểm O
    \coordinate [label=below right:$O$] (O) at (0,0);

    % Định nghĩa các đỉnh của tam giác đều ABC
    \coordinate [label=above:$A$] (A) at (90:3);
    \coordinate [label=below left:$B$] (B) at (210:3);
    \coordinate [label=below right:$C$] (C) at (330:3);

    % Vẽ tam giác ABC
    \draw[thick] (A) -- (B) -- (C) -- cycle;
    \coordinate [label=below:$H$] (H) at ($(B)!0.5!(C)$);

        % Vẽ đường cao AH
        \draw[ thick] (A) -- (H);
            \draw[ thick] (B) -- (O);
                \draw[ thick] (C) -- (O);
\end{tikzpicture}

\end{center}
Ta có $AO= \dfrac{2}{3} AH$ vậy $AH = 9cm$\\
$HB=AH \cot{60^{\circ} } =3 \sqrt{3}cm$\\
$S=\dfrac{1}{2}. BC.AH=HB.AH= 27 \sqrt{3}cm$
}\end{ex}

